import * as React from "react";

// Landscape-first refers to the 3-column customer / master-detail layouts —
// iPad landscape (1024x768) and larger. Anything below (portrait iPad,
// mobile) falls back to the single-column variant with sticky bars.
const LANDSCAPE_MIN_WIDTH = 1024;

export function useIsLandscape(): boolean {
  const [isLandscape, setIsLandscape] = React.useState<boolean>(() => {
    if (typeof window === "undefined") return true;
    return window.innerWidth >= LANDSCAPE_MIN_WIDTH;
  });

  React.useEffect(() => {
    const mql = window.matchMedia(`(min-width: ${LANDSCAPE_MIN_WIDTH}px)`);
    const onChange = () => setIsLandscape(mql.matches);
    mql.addEventListener("change", onChange);
    setIsLandscape(mql.matches);
    return () => mql.removeEventListener("change", onChange);
  }, []);

  return isLandscape;
}
