import { CalendarClock } from "lucide-react";
import { useState } from "react";
import { useTranslate } from "ra-core";
import { useGetIdentity } from "ra-core";

import { Button } from "@/components/ui/button";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";

import { Icon } from "@/lago/ui/Icon";
import { useIsLagoAdmin } from "@/lago/auth/useIsLagoAdmin";
import { PlanVisitDialog } from "@/lago/registrer/PlanVisitDialog";
import { RegistrerButton } from "@/lago/registrer/RegistrerButton";

import type { LagoCustomerData } from "../types";

interface RegistrationRailProps {
  data: LagoCustomerData;
}

/**
 * Fixed right-hand column on the customer page. Beslutning A (brief 10):
 * den grønne "Registrér"-knap er eneste registrerings-indgang for
 * historiske hændelser. Brief 15 tilføjer "Planlæg besøg" som separat
 * fremtidig handling — samme rail, forskellig tid-akse.
 */
export function RegistrationRail(props: RegistrationRailProps) {
  const translate = useTranslate();
  return (
    <Card>
      <CardHeader className="pb-3">
        <CardTitle className="text-base font-bold">
          {translate("lago.customer.sections.registration")}
        </CardTitle>
      </CardHeader>
      <CardContent>
        <RegistrationRailContent {...props} />
      </CardContent>
    </Card>
  );
}

export function RegistrationRailContent({ data }: RegistrationRailProps) {
  const translate = useTranslate();
  const { data: identity } = useGetIdentity();
  const { isAdmin } = useIsLagoAdmin();
  const mySalesId = typeof identity?.id === "number" ? identity.id : null;

  // Brief 15: global rolle — sælger må planlægge på egne kunder,
  // admin/backoffice på tværs. Aldrig person-bundet i koden.
  const canPlan =
    isAdmin ||
    (mySalesId != null && data.company.sales_id === mySalesId);

  const [planOpen, setPlanOpen] = useState(false);
  const ext = data.extension;
  const plannedIso = ext?.next_visit_planned ?? null;
  const plannedNote = ext?.next_visit_note ?? null;

  const planLabel = plannedIso
    ? translate("lago.plan_visit.rail_button_edit")
    : translate("lago.plan_visit.rail_button_new");

  return (
    <div className="space-y-3">
      <RegistrerButton
        variant="large"
        companyId={data.company.id}
        companyName={data.company.name}
      />
      <p className="text-muted-foreground text-sm">
        {translate("lago.registrer.button_hint")}
      </p>
      {canPlan && (
        <>
          <Button
            variant="outline"
            className="h-11 w-full justify-start gap-2 text-sm font-bold"
            onClick={() => setPlanOpen(true)}
          >
            <Icon icon={CalendarClock} className="text-blue-600" />
            {planLabel}
          </Button>
          {plannedIso && (
            <p className="text-muted-foreground text-sm">
              {translate("lago.plan_visit.rail_current", {
                when: formatPlannedForRail(plannedIso),
              })}
              {plannedNote && (
                <span className="text-foreground/80 mt-1 block italic">
                  „{plannedNote}"
                </span>
              )}
            </p>
          )}
          <PlanVisitDialog
            open={planOpen}
            onOpenChange={setPlanOpen}
            companyId={data.company.id}
            companyName={data.company.name}
            segment={ext?.segment ?? null}
            currentPlannedIso={plannedIso}
            currentNote={plannedNote}
          />
        </>
      )}
    </div>
  );
}

function formatPlannedForRail(iso: string): string {
  const d = new Date(iso);
  if (Number.isNaN(d.getTime())) return "?";
  const hasClock = d.getHours() !== 0 || d.getMinutes() !== 0;
  return new Intl.DateTimeFormat("da-DK", {
    weekday: "short",
    day: "numeric",
    month: "short",
    ...(hasClock ? { hour: "2-digit", minute: "2-digit" } : {}),
  }).format(d);
}
