import { useMutation, useQuery, useQueryClient } from "@tanstack/react-query";
import { ArrowLeft, Loader2, X } from "lucide-react";
import { useState } from "react";
import { useNavigate, useParams } from "react-router-dom";
import { useTranslate } from "ra-core";

import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import {
  Accordion,
  AccordionContent,
  AccordionItem,
  AccordionTrigger,
} from "@/components/ui/accordion";
import { Icon } from "@/lago/ui/Icon";

import { useIsLandscape } from "@/lago/layout/useIsLandscape";

import { fetchLagoCustomer, upsertLagoExtension } from "./dataAccess";
import type { LagoCustomerData, SaveExtensionInput } from "./types";
import { CustomerTimeline } from "./show/CustomerTimeline";
import { InfoRailCards, SegmentBadge } from "./show/InfoRail";
import {
  RegistrationRail,
  RegistrationRailContent,
} from "./show/RegistrationRail";
import { SalesDevelopmentPanel } from "./show/SalesDevelopmentPanel";

function CustomerHeader({ data }: { data: LagoCustomerData }) {
  const translate = useTranslate();
  const navigate = useNavigate();
  const { company, extension } = data;
  return (
    <div className="bg-background sticky top-0 z-10 border-b">
      <div className="flex items-center gap-3 px-4 py-3">
        <Button
          variant="ghost"
          size="sm"
          onClick={() => navigate("/companies")}
        >
          <Icon icon={ArrowLeft} size="sm" />
          {translate("ra.action.back", { _: "Tilbage" })}
        </Button>
        <div className="flex-1 min-w-0">
          <h1 className="truncate text-lg font-bold sm:text-xl">
            {company.name}
          </h1>
          <div className="text-muted-foreground flex items-center gap-2 text-sm">
            {extension?.visma_customer_no ? (
              <span>
                {translate("lago.customer.visma_no")}:{" "}
                <span className="font-mono">{extension.visma_customer_no}</span>
              </span>
            ) : (
              <span className="italic">
                {translate("lago.customer.no_visma_no")}
              </span>
            )}
            <SegmentBadge segment={extension?.segment} />
          </div>
        </div>
      </div>
    </div>
  );
}

interface ZoneProps {
  data: LagoCustomerData;
  onUpdate: (input: SaveExtensionInput) => void;
  saving: boolean;
}

function LandscapeZones({ data, onUpdate, saving }: ZoneProps) {
  return (
    <div className="grid grid-cols-12 gap-6 px-4 py-4">
      <aside className="col-span-4 xl:col-span-3">
        <InfoRailCards data={data} onUpdate={onUpdate} saving={saving} />
      </aside>
      <main className="col-span-5 xl:col-span-6">
        <CustomerTimeline
          notes={data.notes}
          tasks={data.openTasks}
          extension={data.extension}
          contacts={data.contacts}
          activities={data.activities}
        />
        <SalesDevelopmentPanel />
      </main>
      <aside className="col-span-3">
        <div className="sticky top-20">
          <RegistrationRail data={data} />
        </div>
      </aside>
    </div>
  );
}

function PortraitFallback({ data, onUpdate, saving }: ZoneProps) {
  const translate = useTranslate();
  const [registerOpen, setRegisterOpen] = useState(false);
  return (
    <>
      <div className="px-4 py-4 pb-24">
        <CustomerTimeline
          notes={data.notes}
          tasks={data.openTasks}
          extension={data.extension}
          contacts={data.contacts}
          activities={data.activities}
        />
        <SalesDevelopmentPanel />
        <Accordion type="multiple" defaultValue={["core"]} className="mt-4">
          <AccordionItem value="core">
            <AccordionTrigger>
              {translate("lago.customer.sections.core_info")}
            </AccordionTrigger>
            <AccordionContent>
              <InfoRailCards
                data={data}
                onUpdate={onUpdate}
                saving={saving}
              />
            </AccordionContent>
          </AccordionItem>
        </Accordion>
      </div>
      <div className="bg-background fixed bottom-0 left-0 right-0 z-20 border-t px-4 py-3 shadow-lg">
        {registerOpen ? (
          <div className="max-h-[70vh] overflow-y-auto pb-2">
            <div className="mb-2 flex items-center justify-between">
              <Badge variant="secondary" className="font-normal">
                {translate("lago.customer.sections.registration")}
              </Badge>
              <Button
                variant="ghost"
                size="icon"
                aria-label={translate("ra.action.close", { _: "Luk" })}
                onClick={() => setRegisterOpen(false)}
              >
                <Icon icon={X} size="sm" />
              </Button>
            </div>
            <RegistrationRailContent data={data} />
          </div>
        ) : (
          <div className="flex flex-wrap items-center gap-2">
            <Button size="sm" onClick={() => setRegisterOpen(true)}>
              {translate("lago.customer.sections.registration")}
            </Button>
          </div>
        )}
      </div>
    </>
  );
}

/**
 * LAGO customer page — Domain-brief 3 mid-fi refinement of the kerne-
 * kundebillede. Landscape (>= 1024px) shows three zones: info-rail (left),
 * combined timeline + salgsudvikling (centre), and a fixed registration
 * column (right). Portrait falls back to a single-column view with an
 * accordion for info-cards and a sticky action bar that expands into the
 * full registration surface.
 */
export function LagoCustomerShow() {
  const params = useParams<{ id: string }>();
  const translate = useTranslate();
  const queryClient = useQueryClient();
  const isLandscape = useIsLandscape();
  const companyId = params.id ? Number(params.id) : NaN;

  const query = useQuery({
    queryKey: ["lago-customer", companyId],
    queryFn: () => fetchLagoCustomer(companyId),
    enabled: Number.isFinite(companyId),
  });

  const mutation = useMutation({
    mutationFn: upsertLagoExtension,
    onSuccess: () =>
      queryClient.invalidateQueries({
        queryKey: ["lago-customer", companyId],
      }),
  });

  if (!Number.isFinite(companyId)) {
    return (
      <div className="p-6 text-sm text-destructive">
        {translate("lago.customer.errors.bad_id")}
      </div>
    );
  }

  if (query.isLoading) {
    return (
      <div className="flex items-center gap-2 p-6 text-sm text-muted-foreground">
        <Icon icon={Loader2} className="animate-spin" />
        {translate("lago.customer.loading")}
      </div>
    );
  }

  if (query.error || !query.data) {
    return (
      <div className="p-6 text-sm text-destructive">
        {translate("lago.customer.errors.load_failed", {
          _: "Kunne ikke hente kunden.",
        })}{" "}
        {(query.error as Error | undefined)?.message}
      </div>
    );
  }

  const data = query.data;
  const zoneProps: ZoneProps = {
    data,
    onUpdate: mutation.mutate,
    saving: mutation.isPending,
  };

  return (
    <div className="mx-auto max-w-screen-2xl">
      <CustomerHeader data={data} />
      {isLandscape ? (
        <LandscapeZones {...zoneProps} />
      ) : (
        <PortraitFallback {...zoneProps} />
      )}
    </div>
  );
}
