// @ts-expect-error -- vite-plugin-pwa's virtual module ships types via
// `vite-plugin-pwa/client`, but the @types reference isn't wired into this
// project. The hook itself is stable runtime API.
import { useRegisterSW } from "virtual:pwa-register/react";
import { useEffect } from "react";

// Hvor ofte spørger vi browseren om der findes en ny service-worker.
// Sælgeren kan lade en tab stå åben hele dagen; 60 sek. er en fornuftig
// mellemvej mellem "opdater hurtigt" og "hamr ikke serveren".
const UPDATE_CHECK_INTERVAL_MS = 60_000;

/**
 * Silent PWA auto-update med aggressiv opdaterings-strategi:
 *
 *  1. `registerType: "autoUpdate"` + `skipWaiting`/`clientsClaim` i
 *     workbox-konfigen sikrer at en ny SW aktiveres med det samme og
 *     overtager alle åbne klienter.
 *  2. Denne komponent kalder `registration.update()` med jævne
 *     mellemrum (60s) OG når `visibilitychange`-eventet fyrer — det
 *     sikrer at browseren tjekker for en ny bundle når sælgeren vender
 *     tilbage til en gammel tab.
 *  3. Hvis `needRefresh` fyrer, tvinger vi `updateServiceWorker(true)`
 *     som skipWaiter'er og reloader — så sælgeren ikke behøver
 *     hard-refreshe efter en LAGO-deploy.
 */
export function LagoPwaAutoUpdate() {
  const { needRefresh, updateServiceWorker } = useRegisterSW({
    immediate: true,
    onRegisteredSW(_swUrl: string, registration?: ServiceWorkerRegistration) {
      if (!registration) return;

      const tryUpdate = () => {
        registration.update().catch(() => {
          /* offline eller network fail — ignorér */
        });
      };

      // Periodisk check.
      window.setInterval(tryUpdate, UPDATE_CHECK_INTERVAL_MS);

      // Tab-genoptagelse → check straks.
      document.addEventListener("visibilitychange", () => {
        if (document.visibilityState === "visible") tryUpdate();
      });
    },
  });

  const [shouldRefresh] = needRefresh;

  useEffect(() => {
    if (shouldRefresh) {
      updateServiceWorker(true);
    }
  }, [shouldRefresh, updateServiceWorker]);

  return null;
}
