import { useDeferredValue, useMemo, useState } from "react";
import { useQuery } from "@tanstack/react-query";
import { ChevronLeft, ChevronRight, Loader2, MapPin, Search, User } from "lucide-react";
import { useGetIdentity, useTranslate } from "ra-core";

import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Card, CardContent } from "@/components/ui/card";
import { Input } from "@/components/ui/input";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import {
  Sheet,
  SheetContent,
  SheetHeader,
  SheetTitle,
} from "@/components/ui/sheet";
import { cn } from "@/lib/utils";
import { Icon } from "@/lago/ui/Icon";
import { StatusPill, type StatusVariant } from "@/lago/ui/StatusPill";

import { useIsLandscape } from "@/lago/layout/useIsLandscape";

import { useSellerLookup } from "@/lago/settings/useSellerLookup";
import { useVisitIntervals } from "@/lago/settings/useVisitIntervals";

import { fetchCustomerList, type CustomerListRow } from "./dataAccess";
import { CustomerPreview } from "./list/CustomerPreview";
import {
  comparePriority,
  computeVisitPriority,
  type VisitPriority,
  type VisitStatus,
} from "./priority";
import { SEGMENT_INTERVAL_DAYS, type Segment } from "./segmentIntervals";

type SortMode = "name" | "priority" | "last_visit";
type VisitFilter = "any" | "never" | "over30" | "over60";

// Brief 13: A/B/C/X/L overalt. Kun A/B/C har interval — X og L er
// "uklassificeret"/"lead" og opererer på default-intervallet.
const SEGMENTS: Segment[] = ["A", "B", "C", "X", "L"];
const SEGMENT_INTERVAL_HINT: Record<Segment, string> = {
  A: `Interval: hver ${SEGMENT_INTERVAL_DAYS.A}. dag`,
  B: `Interval: hver ${SEGMENT_INTERVAL_DAYS.B}. dag`,
  C: `Interval: hver ${SEGMENT_INTERVAL_DAYS.C}. dag`,
  X: "Uklassificeret — bruger default-interval",
  L: "Lead — bruger default-interval",
};
const ALL_SENTINEL = "__all__";
const PAGE_SIZE_OPTIONS = [25, 50, 100];
const DEFAULT_PAGE_SIZE = 50;

interface EnrichedRow extends CustomerListRow {
  priority: VisitPriority;
}

function statusDotClass(status: VisitStatus): string {
  switch (status) {
    case "overdue":
    case "never_visited":
      // Brief 14 (rettelse): aldrig-besøgt A/B/C er rød — "skal besøges".
      return "bg-red-500";
    case "soon":
      return "bg-amber-500";
    case "on_plan":
      return "bg-emerald-500";
    default:
      // no_urgency (X/L) — grå, ingen kadence.
      return "bg-muted-foreground/40";
  }
}

function statusPillVariant(status: VisitStatus): StatusVariant {
  switch (status) {
    case "overdue":
    case "never_visited":
      return "red";
    case "soon":
      return "amber";
    case "on_plan":
      return "green";
    default:
      return "grey";
  }
}

function PriorityBadge({
  priority,
  translate,
}: {
  priority: VisitPriority;
  translate: ReturnType<typeof useTranslate>;
}) {
  let label: string;
  if (priority.status === "never_visited") {
    label = translate("lago.customer_list.status.never_visited");
  } else if (priority.status === "overdue") {
    label = translate("lago.customer_list.status.overdue_by_n", {
      smart_count: priority.daysOverdue ?? 0,
    });
  } else if (priority.status === "soon") {
    label = translate("lago.customer_list.status.soon");
  } else {
    label = translate("lago.customer_list.status.on_plan");
  }
  return (
    <StatusPill variant={statusPillVariant(priority.status)}>
      {label}
    </StatusPill>
  );
}

function lastVisitPhrase(
  priority: VisitPriority,
  translate: ReturnType<typeof useTranslate>,
): string {
  const days = priority.daysSinceVisit;
  if (days == null) {
    return translate("lago.customer_list.never_visited_soft");
  }
  if (days <= 0) return translate("lago.customer_list.last_visit_today");
  if (days === 1) return translate("lago.customer_list.last_visit_yesterday");
  return translate("lago.customer_list.last_visit_n_days_ago", { n: days });
}

interface CustomerRowProps {
  row: EnrichedRow;
  selected: boolean;
  onSelect: (id: number) => void;
  emphasisePriority: boolean;
}

function CustomerRow({
  row,
  selected,
  onSelect,
  emphasisePriority,
}: CustomerRowProps) {
  const translate = useTranslate();
  const sellers = useSellerLookup();
  const { name, city, extension, priority } = row;
  const distrikt = extension?.distrikt;
  const segment = extension?.segment;
  const salesName =
    sellers.byCode(extension?.visma_sales_code) ??
    extension?.visma_sales_name ??
    null;
  return (
    <button
      type="button"
      onClick={() => onSelect(row.id)}
      className={cn(
        "block w-full text-left focus-visible:outline-none",
        selected && "ring-primary rounded-md ring-2 ring-offset-1",
      )}
    >
      <Card className="hover:bg-muted/40 active:bg-muted/60 transition-colors">
        <CardContent className="flex items-center gap-3 py-2.5">
          <div
            className={cn(
              "h-2 w-2 flex-shrink-0 rounded-full",
              statusDotClass(priority.status),
            )}
            aria-hidden
          />
          <div className="min-w-0 flex-1">
            <div className="flex flex-wrap items-baseline gap-x-2 gap-y-0.5">
              <h3 className="truncate text-sm font-bold">{name}</h3>
              {segment && (
                <Badge
                  variant="secondary"
                  className="flex-shrink-0 font-normal"
                >
                  {segment}
                </Badge>
              )}
              {distrikt && (
                <Badge
                  variant="outline"
                  className="flex-shrink-0 font-normal text-sm"
                >
                  {distrikt}
                </Badge>
              )}
            </div>
            <p className="text-muted-foreground mt-0.5 flex flex-wrap items-center gap-x-2 gap-y-0.5 text-sm">
              {city && (
                <span className="inline-flex items-center gap-1">
                  <Icon icon={MapPin} size="sm" /> {city}
                </span>
              )}
              {salesName && (
                <>
                  <span aria-hidden>·</span>
                  <span className="inline-flex items-center gap-1">
                    <Icon icon={User} size="sm" />
                    {salesName}
                  </span>
                </>
              )}
              <span aria-hidden>·</span>
              <span
                className={
                  priority.status === "never_visited" ? "italic" : undefined
                }
              >
                {lastVisitPhrase(priority, translate)}
              </span>
            </p>
          </div>
          {emphasisePriority && priority.status !== "on_plan" && (
            <div className="flex-shrink-0">
              <PriorityBadge priority={priority} translate={translate} />
            </div>
          )}
        </CardContent>
      </Card>
    </button>
  );
}

/**
 * LAGO customer list at scale (Domain-brief 8, refining brief 3b).
 * Landscape: filtered list on the left + fetched preview on the right.
 * Portrait: single-column list; tapping a row opens a bottom-sheet with
 * the same preview surface. Default sort is alphabetical (a normal,
 * browsable list); priority is available as an opt-in sort. All existing
 * Atomic-side filters are preserved and joined by the new distrikt +
 * sælger pickers now that we have real data.
 */
export function LagoCustomerList() {
  const translate = useTranslate();
  const isLandscape = useIsLandscape();
  const { data: identity } = useGetIdentity();
  const mySalesId = typeof identity?.id === "number" ? identity.id : null;

  const [search, setSearch] = useState("");
  const deferredSearch = useDeferredValue(search);
  const [sortMode, setSortMode] = useState<SortMode>("name");
  const [activeSegments, setActiveSegments] = useState<Set<Segment>>(new Set());
  const [needsVisitOnly, setNeedsVisitOnly] = useState(false);
  const [onlyMine, setOnlyMine] = useState(false);
  const [visitFilter, setVisitFilter] = useState<VisitFilter>("any");
  const [distrikt, setDistrikt] = useState<string>(ALL_SENTINEL);
  const [salesName, setSalesName] = useState<string>(ALL_SENTINEL);
  const [pageSize, setPageSize] = useState<number>(DEFAULT_PAGE_SIZE);
  const [page, setPage] = useState<number>(1);
  const [selectedId, setSelectedId] = useState<number | null>(null);
  const [sheetOpen, setSheetOpen] = useState(false);
  // Brief 13: default kun aktive kunder vises. Toggle for at inkludere
  // inaktive (fx til historik-genfinding).
  const [showInactive, setShowInactive] = useState(false);
  // Brief 14: leads (L) skjules som default. Toggle for at se dem.
  const [showLeads, setShowLeads] = useState(false);

  const intervals = useVisitIntervals();
  const query = useQuery({
    queryKey: ["lago-customer-list", { onlyMine, mySalesId }],
    queryFn: () => fetchCustomerList({ mySalesId, onlyMine }),
  });

  const distinctDistrikter = useMemo(() => {
    const set = new Set<string>();
    for (const r of query.data ?? []) {
      if (r.extension?.distrikt) set.add(r.extension.distrikt);
    }
    return [...set].sort((a, b) => a.localeCompare(b, "da"));
  }, [query.data]);

  const sellers = useSellerLookup();
  const distinctSalesNames = useMemo(() => {
    const set = new Set<string>();
    for (const r of query.data ?? []) {
      const name =
        sellers.byCode(r.extension?.visma_sales_code) ??
        r.extension?.visma_sales_name ??
        null;
      if (name) set.add(name);
    }
    return [...set].sort((a, b) => a.localeCompare(b, "da"));
  }, [query.data, sellers]);

  const rows = useMemo<EnrichedRow[]>(() => {
    if (!query.data) return [];
    const needle = deferredSearch.trim().toLowerCase();
    const enriched: EnrichedRow[] = query.data.map((c) => ({
      ...c,
      priority: computeVisitPriority(
        c.extension?.last_visit_at,
        c.extension?.segment,
        new Date(),
        intervals,
      ),
    }));
    const filtered = enriched.filter((r) => {
      // Brief 13: aktive vises default. showInactive slår gate fra.
      if (!showInactive && r.extension?.is_active === false) return false;
      // Brief 14: leads (L) skjules som default. showLeads slår gate fra.
      if (!showLeads && r.extension?.segment === "L") return false;
      if (needle) {
        const hay =
          `${r.name} ${r.city ?? ""} ${r.extension?.visma_customer_no ?? ""}`.toLowerCase();
        if (!hay.includes(needle)) return false;
      }
      if (activeSegments.size > 0) {
        if (!r.extension?.segment) return false;
        if (!activeSegments.has(r.extension.segment as Segment)) return false;
      }
      if (distrikt !== ALL_SENTINEL) {
        if (r.extension?.distrikt !== distrikt) return false;
      }
      if (salesName !== ALL_SENTINEL) {
        const resolved =
          sellers.byCode(r.extension?.visma_sales_code) ??
          r.extension?.visma_sales_name ??
          null;
        if (resolved !== salesName) return false;
      }
      if (needsVisitOnly) {
        if (
          r.priority.status !== "overdue" &&
          r.priority.status !== "never_visited"
        ) {
          return false;
        }
      }
      if (visitFilter !== "any") {
        const days = r.priority.daysSinceVisit;
        if (visitFilter === "never" && days != null) return false;
        if (visitFilter === "over30" && (days == null || days <= 30))
          return false;
        if (visitFilter === "over60" && (days == null || days <= 60))
          return false;
      }
      return true;
    });
    if (sortMode === "priority") {
      return filtered.sort((a, b) => comparePriority(a.priority, b.priority));
    }
    if (sortMode === "last_visit") {
      return filtered.sort((a, b) => {
        const aT = a.extension?.last_visit_at ?? "";
        const bT = b.extension?.last_visit_at ?? "";
        return bT.localeCompare(aT);
      });
    }
    return filtered.sort((a, b) =>
      a.name.localeCompare(b.name, "da", { sensitivity: "base" }),
    );
  }, [
    query.data,
    deferredSearch,
    activeSegments,
    distrikt,
    salesName,
    needsVisitOnly,
    sortMode,
    visitFilter,
    intervals,
    sellers,
    showInactive,
    showLeads,
  ]);

  const counts = useMemo(() => {
    const c = {
      overdue: 0,
      soon: 0,
      on_plan: 0,
      never_visited: 0,
      no_urgency: 0,
    } as Record<VisitStatus, number>;
    for (const r of rows) c[r.priority.status]++;
    return c;
  }, [rows]);

  // Reset pagination whenever the filtered set shrinks/grows so we never
  // land on an empty page.
  const totalPages = Math.max(1, Math.ceil(rows.length / pageSize));
  const currentPage = Math.min(page, totalPages);
  const pageStart = (currentPage - 1) * pageSize;
  const pageEnd = Math.min(rows.length, pageStart + pageSize);
  const visibleRows = rows.slice(pageStart, pageEnd);

  const toggleSegment = (s: Segment) => {
    setActiveSegments((prev) => {
      const next = new Set(prev);
      if (next.has(s)) next.delete(s);
      else next.add(s);
      return next;
    });
    setPage(1);
  };

  const handleSelect = (id: number) => {
    setSelectedId(id);
    if (!isLandscape) setSheetOpen(true);
  };

  const emphasisePriority = sortMode === "priority" || needsVisitOnly;

  return (
    <div className="mx-auto max-w-screen-2xl">
      <div className="grid grid-cols-1 gap-4 px-3 py-4 sm:px-4 lg:grid-cols-12">
        <div className="lg:col-span-7">
          <header className="mb-3 flex items-baseline justify-between gap-3">
            <h1 className="text-lg font-bold">
              {translate("lago.customer_list.title")}
            </h1>
            <span className="text-muted-foreground text-sm">
              {translate("lago.customer_list.summary", {
                smart_count: rows.length,
                total: rows.length,
                overdue: counts.overdue + counts.never_visited,
                soon: counts.soon,
              })}
            </span>
          </header>

          <div className="mb-2 flex flex-col gap-2 sm:flex-row sm:items-center">
            <div className="relative flex-1">
              <Icon icon={Search} className="text-muted-foreground pointer-events-none absolute top-1/2 left-3 -translate-y-1/2" />
              <Input
                type="search"
                value={search}
                onChange={(e) => {
                  setSearch(e.target.value);
                  setPage(1);
                }}
                placeholder={translate(
                  "lago.customer_list.search_placeholder",
                )}
                className="pl-9"
              />
            </div>
            <Select
              value={sortMode}
              onValueChange={(v) => {
                setSortMode(v as SortMode);
                setPage(1);
              }}
            >
              <SelectTrigger className="sm:w-[240px]">
                <SelectValue />
              </SelectTrigger>
              <SelectContent>
                <SelectItem value="name">
                  {translate("lago.customer_list.sort.name")}
                </SelectItem>
                <SelectItem value="priority">
                  {translate("lago.customer_list.sort.priority")}
                </SelectItem>
                <SelectItem value="last_visit">
                  {translate("lago.customer_list.sort.last_visit")}
                </SelectItem>
              </SelectContent>
            </Select>
          </div>

          <div className="mb-3 flex flex-wrap items-center gap-1.5">
            {SEGMENTS.map((s) => {
              const active = activeSegments.has(s);
              return (
                <Button
                  key={s}
                  size="sm"
                  variant={active ? "default" : "outline"}
                  onClick={() => toggleSegment(s)}
                  className="h-7 px-2"
                  title={SEGMENT_INTERVAL_HINT[s]}
                >
                  {s}
                </Button>
              );
            })}
            <span className="bg-border mx-1 h-4 w-px" aria-hidden />
            <Select
              value={distrikt}
              onValueChange={(v) => {
                setDistrikt(v);
                setPage(1);
              }}
            >
              <SelectTrigger className="h-7 w-auto px-2 text-sm">
                <SelectValue />
              </SelectTrigger>
              <SelectContent>
                <SelectItem value={ALL_SENTINEL}>
                  {translate("lago.customer_list.filter_district_all")}
                </SelectItem>
                {distinctDistrikter.map((d) => (
                  <SelectItem key={d} value={d}>
                    {d}
                  </SelectItem>
                ))}
              </SelectContent>
            </Select>
            <Select
              value={salesName}
              onValueChange={(v) => {
                setSalesName(v);
                setPage(1);
              }}
            >
              <SelectTrigger className="h-7 w-auto px-2 text-sm">
                <SelectValue />
              </SelectTrigger>
              <SelectContent>
                <SelectItem value={ALL_SENTINEL}>
                  {translate("lago.customer_list.filter_sales_all")}
                </SelectItem>
                {distinctSalesNames.map((n) => (
                  <SelectItem key={n} value={n}>
                    {n}
                  </SelectItem>
                ))}
              </SelectContent>
            </Select>
            <Select
              value={visitFilter}
              onValueChange={(v) => {
                setVisitFilter(v as VisitFilter);
                setPage(1);
              }}
            >
              <SelectTrigger className="h-7 w-auto px-2 text-sm">
                <SelectValue />
              </SelectTrigger>
              <SelectContent>
                <SelectItem value="any">
                  {translate("lago.customer_list.filter_visit_any")}
                </SelectItem>
                <SelectItem value="never">
                  {translate("lago.customer_list.filter_visit_never")}
                </SelectItem>
                <SelectItem value="over30">
                  {translate("lago.customer_list.filter_visit_over_30")}
                </SelectItem>
                <SelectItem value="over60">
                  {translate("lago.customer_list.filter_visit_over_60")}
                </SelectItem>
              </SelectContent>
            </Select>
            <span className="bg-border mx-1 h-4 w-px" aria-hidden />
            <Button
              size="sm"
              variant={needsVisitOnly ? "default" : "outline"}
              onClick={() => {
                setNeedsVisitOnly((v) => !v);
                setPage(1);
              }}
              className="h-7 px-2"
            >
              {translate("lago.customer_list.filter_needs_visit")}
            </Button>
            <Button
              size="sm"
              variant={onlyMine ? "default" : "outline"}
              onClick={() => {
                setOnlyMine((v) => !v);
                setPage(1);
              }}
              className="h-7 px-2"
              disabled={mySalesId == null}
            >
              {translate("lago.customer_list.filter_mine")}
            </Button>
            <Button
              size="sm"
              variant={showInactive ? "default" : "outline"}
              onClick={() => {
                setShowInactive((v) => !v);
                setPage(1);
              }}
              className="h-7 px-2"
              title="Vis også inaktive kunder"
            >
              Vis inaktive
            </Button>
            <Button
              size="sm"
              variant={showLeads ? "default" : "outline"}
              onClick={() => {
                setShowLeads((v) => !v);
                setPage(1);
              }}
              className="h-7 px-2"
              title="Vis også leads (segment L)"
            >
              Vis leads
            </Button>
          </div>

          {query.isLoading ? (
            <div className="text-muted-foreground flex items-center gap-2 py-6 text-sm">
              <Icon icon={Loader2} className="animate-spin" />
              {translate("lago.customer_list.loading")}
            </div>
          ) : query.error ? (
            <p className="text-destructive py-4 text-sm">
              {translate("lago.customer_list.load_failed")}{" "}
              {(query.error as Error).message}
            </p>
          ) : rows.length === 0 ? (
            <p className="text-muted-foreground py-6 text-sm">
              {translate("lago.customer_list.empty")}
            </p>
          ) : (
            <>
              <ul className="space-y-1.5">
                {visibleRows.map((row) => (
                  <li key={row.id}>
                    <CustomerRow
                      row={row}
                      selected={row.id === selectedId}
                      onSelect={handleSelect}
                      emphasisePriority={emphasisePriority}
                    />
                  </li>
                ))}
              </ul>
              <PaginationBar
                page={currentPage}
                totalPages={totalPages}
                from={rows.length === 0 ? 0 : pageStart + 1}
                to={pageEnd}
                total={rows.length}
                pageSize={pageSize}
                onPageChange={setPage}
                onPageSizeChange={(v) => {
                  setPageSize(v);
                  setPage(1);
                }}
              />
            </>
          )}
        </div>

        {isLandscape && (
          <aside className="lg:col-span-5">
            <div className="sticky top-20">
              <CustomerPreview companyId={selectedId} />
            </div>
          </aside>
        )}
      </div>

      {!isLandscape && (
        <Sheet open={sheetOpen} onOpenChange={setSheetOpen}>
          <SheetContent
            side="bottom"
            className="max-h-[85vh] overflow-y-auto"
          >
            <SheetHeader>
              <SheetTitle>
                {translate("lago.customer_list.preview.bottom_sheet_label")}
              </SheetTitle>
            </SheetHeader>
            <div className="mt-4">
              <CustomerPreview companyId={selectedId} />
            </div>
          </SheetContent>
        </Sheet>
      )}
    </div>
  );
}

interface PaginationBarProps {
  page: number;
  totalPages: number;
  from: number;
  to: number;
  total: number;
  pageSize: number;
  onPageChange: (p: number) => void;
  onPageSizeChange: (n: number) => void;
}

function PaginationBar({
  page,
  totalPages,
  from,
  to,
  total,
  pageSize,
  onPageChange,
  onPageSizeChange,
}: PaginationBarProps) {
  const translate = useTranslate();
  if (total === 0) return null;
  return (
    <div className="text-muted-foreground mt-4 flex flex-wrap items-center justify-between gap-3 text-sm">
      <span>
        {translate("lago.customer_list.pagination.showing", { from, to, total })}
      </span>
      <div className="flex items-center gap-3">
        <div className="flex items-center gap-1">
          <span>{translate("lago.customer_list.pagination.page_size")}</span>
          <Select
            value={String(pageSize)}
            onValueChange={(v) => onPageSizeChange(Number(v))}
          >
            <SelectTrigger className="h-7 w-[70px] text-sm">
              <SelectValue />
            </SelectTrigger>
            <SelectContent>
              {PAGE_SIZE_OPTIONS.map((s) => (
                <SelectItem key={s} value={String(s)}>
                  {s}
                </SelectItem>
              ))}
            </SelectContent>
          </Select>
        </div>
        <Button
          size="sm"
          variant="outline"
          className="h-7 px-2"
          disabled={page <= 1}
          onClick={() => onPageChange(page - 1)}
        >
          <Icon icon={ChevronLeft} size="sm" />
          {translate("lago.customer_list.pagination.prev")}
        </Button>
        <span>
          {translate("lago.customer_list.pagination.page", {
            page,
            total: totalPages,
          })}
        </span>
        <Button
          size="sm"
          variant="outline"
          className="h-7 px-2"
          disabled={page >= totalPages}
          onClick={() => onPageChange(page + 1)}
        >
          {translate("lago.customer_list.pagination.next")}
          <Icon icon={ChevronRight} size="sm" />
        </Button>
      </div>
    </div>
  );
}
