/**
 * LAGO topnav (Domain-brief 3e). Same visual shell as upstream's Header
 * but the tab order and labels are LAGO's:
 * Hjem · Kunder · Kontakter · Salgsudvikling · Aftaler (dæmpet).
 * "Aftaler" is deliberately kept — visually toned down until the pipeline
 * is relevant to the field-test — never hidden.
 */
export function LagoHeader() {
  const { darkModeLogo, lightModeLogo, title } = useConfigurationContext();
  const location = useLocation();
  const translate = useTranslate();
  const { isAdmin } = useIsLagoAdmin();
  const [drawerOpen, setDrawerOpen] = useState(false);

  const currentPath = detectCurrentPath(location.pathname);

  // Brief 16 (#2): luk drawer'en når ruten skifter, så sælger ikke ser
  // en åben menu efter tap på et link.
  useEffect(() => {
    setDrawerOpen(false);
  }, [location.pathname]);

  const navItems = (
    <>
      <NavTab
        to="/felt/dagens"
        icon={<Icon icon={Target} />}
        label={translate("lago.nav.felt")}
        isActive={currentPath === "/felt"}
        title={translate("lago.nav.felt_hint")}
      />
      <NavTab
        to="/"
        icon={<Icon icon={Home} />}
        label={translate("lago.nav.home")}
        isActive={currentPath === "/"}
      />
      <NavTab
        to="/companies"
        icon={<Icon icon={Users2} />}
        label={translate("lago.nav.customers")}
        isActive={currentPath === "/companies"}
      />
      <NavTab
        to="/contacts"
        icon={<Icon icon={Users} />}
        label={translate("lago.nav.contacts")}
        isActive={currentPath === "/contacts"}
      />
      <NavTab
        to="/salgsudvikling"
        icon={<Icon icon={TrendingUp} />}
        label={translate("lago.nav.sales_dev")}
        isActive={currentPath === "/salgsudvikling"}
      />
      <NavTab
        to="/deals"
        icon={<Icon icon={Handshake} />}
        label={translate("lago.nav.deals")}
        isActive={currentPath === "/deals"}
        muted
        title={translate("lago.nav.deals_muted_hint")}
      />
      {isAdmin && (
        <NavTab
          to="/indstillinger"
          icon={<Icon icon={SlidersHorizontal} />}
          label={translate("lago.nav.settings")}
          isActive={currentPath === "/indstillinger"}
          title={translate("lago.nav.settings_hint")}
        />
      )}
    </>
  );

  return (
    <nav className="grow">
      <header className="bg-secondary">
        <div className="px-4">
          <div className="flex flex-1 items-center justify-between gap-2">
            {/* Brief 16 (#2): mobil hamburger til venstre — top-nav'en
                kollapser under md så logo + titel ikke wrapper med
                nav-fanerne på iPhone-bredde. */}
            <Button
              variant="ghost"
              size="icon"
              className="text-secondary-foreground min-h-11 md:hidden"
              onClick={() => setDrawerOpen(true)}
              aria-label={translate("lago.nav.menu_open")}
            >
              <Icon icon={Menu} />
            </Button>

            <Link
              to="/"
              className="text-secondary-foreground flex min-w-0 items-center gap-2 no-underline"
            >
              <img
                className="h-6 [.light_&]:hidden"
                src={darkModeLogo}
                alt={title}
              />
              <img
                className="h-6 [.dark_&]:hidden"
                src={lightModeLogo}
                alt={title}
              />
              <h1 className="truncate text-xl font-bold">{title}</h1>
            </Link>

            {/* Vandret nav bevaret uændret på md+ */}
            <nav className="hidden md:flex">{navItems}</nav>

            <div className="flex items-center gap-1">
              <SalgsdataSyncStatus className="hidden sm:inline-flex" />
              <ThemeModeToggle />
              <RefreshButton />
              <UserMenu>
                <ProfileMenu />
                <CanAccess resource="sales" action="list">
                  <UsersMenu />
                </CanAccess>
                <CanAccess resource="configuration" action="edit">
                  <SettingsMenu />
                </CanAccess>
                <ImportFromJsonMenuItem />
                <ChangelogMenuItem />
              </UserMenu>
            </div>
          </div>
        </div>
      </header>

      <Sheet open={drawerOpen} onOpenChange={setDrawerOpen}>
        <SheetContent side="left" className="flex w-72 flex-col p-0">
          <SheetHeader className="border-b p-4">
            <SheetTitle className="flex items-center gap-2">
              <img
                className="h-5 [.light_&]:hidden"
                src={darkModeLogo}
                alt={title}
              />
              <img
                className="h-5 [.dark_&]:hidden"
                src={lightModeLogo}
                alt={title}
              />
              <span>{title}</span>
            </SheetTitle>
          </SheetHeader>
          <div className="flex flex-col py-2">
            <DrawerNavItem
              to="/felt/dagens"
              icon={<Icon icon={Target} />}
              label={translate("lago.nav.felt")}
              isActive={currentPath === "/felt"}
            />
            <DrawerNavItem
              to="/"
              icon={<Icon icon={Home} />}
              label={translate("lago.nav.home")}
              isActive={currentPath === "/"}
            />
            <DrawerNavItem
              to="/companies"
              icon={<Icon icon={Users2} />}
              label={translate("lago.nav.customers")}
              isActive={currentPath === "/companies"}
            />
            <DrawerNavItem
              to="/contacts"
              icon={<Icon icon={Users} />}
              label={translate("lago.nav.contacts")}
              isActive={currentPath === "/contacts"}
            />
            <DrawerNavItem
              to="/salgsudvikling"
              icon={<Icon icon={TrendingUp} />}
              label={translate("lago.nav.sales_dev")}
              isActive={currentPath === "/salgsudvikling"}
            />
            <DrawerNavItem
              to="/deals"
              icon={<Icon icon={Handshake} />}
              label={translate("lago.nav.deals")}
              isActive={currentPath === "/deals"}
              muted
            />
            {isAdmin && (
              <DrawerNavItem
                to="/indstillinger"
                icon={<Icon icon={SlidersHorizontal} />}
                label={translate("lago.nav.settings")}
                isActive={currentPath === "/indstillinger"}
              />
            )}
          </div>
          {/* Synk-status i drawer'ens bund så mobil har samme ene sted
              som desktop-headeren — brief 19 §5 ("ét sted, aldrig som
              forbehold på widgets"). */}
          <div className="mt-auto border-t p-4">
            <SalgsdataSyncStatus tone="on-surface" className="px-0" />
          </div>
        </SheetContent>
      </Sheet>
    </nav>
  );
}

interface DrawerNavItemProps {
  to: string;
  icon: React.ReactNode;
  label: string;
  isActive: boolean;
  muted?: boolean;
}

function DrawerNavItem({
  to,
  icon,
  label,
  isActive,
  muted,
}: DrawerNavItemProps) {
  return (
    <Link
      to={to}
      className={cn(
        "flex items-center gap-3 px-5 py-3 text-sm transition-colors",
        isActive
          ? "bg-muted text-foreground font-bold"
          : "text-foreground/80 hover:bg-muted",
        muted && !isActive && "italic",
      )}
    >
      {icon}
      <span>{label}</span>
    </Link>
  );
}

function detectCurrentPath(pathname: string): string | false {
  if (matchPath("/felt/*", pathname)) return "/felt";
  if (matchPath("/contacts/*", pathname)) return "/contacts";
  if (matchPath("/companies/*", pathname)) return "/companies";
  if (matchPath("/deals/*", pathname)) return "/deals";
  if (matchPath("/salgsudvikling/*", pathname)) return "/salgsudvikling";
  if (matchPath("/indstillinger/*", pathname)) return "/indstillinger";
  if (matchPath("/", pathname)) return "/";
  return false;
}

interface NavTabProps {
  to: string;
  icon: React.ReactNode;
  label: string;
  isActive: boolean;
  muted?: boolean;
  title?: string;
}

function NavTab({ to, icon, label, isActive, muted, title }: NavTabProps) {
  return (
    <Link
      to={to}
      title={title}
      className={cn(
        "inline-flex items-center gap-2 border-b-2 px-4 py-3 text-sm font-medium transition-colors sm:px-6",
        isActive
          ? "text-secondary-foreground border-secondary-foreground"
          : "text-secondary-foreground/70 hover:text-secondary-foreground/80 border-transparent",
      )}
    >
      {icon}
      <span className={muted ? "italic" : undefined}>{label}</span>
    </Link>
  );
}

function UsersMenu() {
  const translate = useTranslate();
  const userMenuContext = useUserMenu();
  if (!userMenuContext) {
    throw new Error("<UsersMenu> must be used inside <UserMenu>");
  }
  return (
    <DropdownMenuItem asChild onClick={userMenuContext.onClose}>
      <Link to="/sales" className="flex items-center gap-2">
        <Icon icon={Users} />
        {translate("resources.sales.name", { smart_count: 2 })}
      </Link>
    </DropdownMenuItem>
  );
}

