import { useMutation, useQuery, useQueryClient } from "@tanstack/react-query";
import { CalendarCheck2, ExternalLink, Loader2, MapPin, Users } from "lucide-react";
import { useState } from "react";
import { Link } from "react-router-dom";
import { useTranslate } from "ra-core";

import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";

import { Icon } from "@/lago/ui/Icon";
import { fetchLagoCustomer, upsertLagoExtension } from "../dataAccess";
import { QuickNoteForm } from "../QuickNoteForm";
import { QuickTaskForm } from "../QuickTaskForm";
import { ContactStatusBadge } from "../show/ContactStatusBadge";
import { VismaBadge } from "../VismaBadge";
import type { ContactSummary } from "../types";

interface CustomerPreviewProps {
  companyId: number | null;
}

function fullName(c: ContactSummary): string {
  return [c.first_name, c.last_name].filter(Boolean).join(" ").trim() || "—";
}

/**
 * Right-hand preview panel for the master-detail customer list.
 * Fetches the same LagoCustomerData shape as the full show page but only
 * renders a condensed summary — kerne-info, contacts w/ status, quick
 * actions, a placeholder for sales development, and a link to the full
 * page (3c). Same component is reused inside the portrait bottom-sheet.
 */
export function CustomerPreview({ companyId }: CustomerPreviewProps) {
  const translate = useTranslate();
  const queryClient = useQueryClient();
  const query = useQuery({
    queryKey: ["lago-customer", companyId],
    queryFn: () => (companyId ? fetchLagoCustomer(companyId) : null),
    enabled: companyId != null,
  });

  const mutation = useMutation({
    mutationFn: upsertLagoExtension,
    onSuccess: () => {
      if (companyId != null) {
        queryClient.invalidateQueries({
          queryKey: ["lago-customer", companyId],
        });
      }
      queryClient.invalidateQueries({ queryKey: ["lago-customer-list"] });
    },
  });

  const [tab, setTab] = useState<"info" | "note" | "task">("info");

  if (companyId == null) {
    return (
      <div className="text-muted-foreground rounded-md border border-dashed p-8 text-center text-sm">
        {translate("lago.customer_list.preview.placeholder")}
      </div>
    );
  }

  if (query.isLoading) {
    return (
      <div className="text-muted-foreground flex items-center gap-2 p-6 text-sm">
        <Icon icon={Loader2} className="animate-spin" />
        {translate("lago.customer.loading")}
      </div>
    );
  }

  if (query.error || !query.data) {
    return (
      <div className="text-destructive p-6 text-sm">
        {translate("lago.customer.errors.load_failed")}
      </div>
    );
  }

  const data = query.data;
  const { company, extension, contacts } = data;
  const primaryContact = contacts[0];
  const address = [company.address, company.zipcode, company.city]
    .filter(Boolean)
    .join(", ");
  const invalidateKey: ReadonlyArray<unknown> = [
    "lago-customer",
    companyId,
  ];

  const markVisited = () =>
    mutation.mutate({
      company_id: company.id,
      last_visit_at: new Date().toISOString(),
    });

  return (
    <div className="space-y-4">
      <Card>
        <CardHeader className="flex flex-row items-start justify-between gap-3 space-y-0 pb-3">
          <div className="min-w-0 flex-1">
            <CardTitle className="truncate text-base font-bold">
              {company.name}
            </CardTitle>
            <div className="text-muted-foreground mt-1 flex flex-wrap items-center gap-2 text-sm">
              {extension?.visma_customer_no ? (
                <span>
                  {translate("lago.customer.visma_no")}:{" "}
                  <span className="font-mono">
                    {extension.visma_customer_no}
                  </span>
                </span>
              ) : (
                <span className="italic">
                  {translate("lago.customer.no_visma_no")}
                </span>
              )}
              {extension?.segment && (
                <Badge variant="secondary" className="font-normal">
                  {translate("lago.customer.segment")} {extension.segment}
                </Badge>
              )}
            </div>
          </div>
          <Button asChild variant="outline" size="sm">
            <Link to={`/companies/${company.id}/show`}>
              <Icon icon={ExternalLink} size="sm" className="mr-1" />
              {translate("lago.customer_list.preview.open_full")}
            </Link>
          </Button>
        </CardHeader>
        <CardContent className="space-y-3 pt-0">
          <div>
            <div className="text-muted-foreground mb-1 text-xs font-bold uppercase tracking-wide">
              {translate("lago.customer_list.preview.quick_actions")}
            </div>
            <div className="flex flex-wrap gap-2">
              <Button
                size="sm"
                variant="secondary"
                onClick={markVisited}
                disabled={mutation.isPending}
              >
                {mutation.isPending ? (
                  <Icon icon={Loader2} size="sm" className="mr-2 animate-spin" />
                ) : (
                  <Icon icon={CalendarCheck2} size="sm" className="mr-1" />
                )}
                {translate("lago.customer_list.preview.mark_visited")}
              </Button>
              <Button
                size="sm"
                variant={tab === "note" ? "default" : "outline"}
                onClick={() => setTab("note")}
              >
                {translate("lago.customer_list.preview.add_note")}
              </Button>
              <Button
                size="sm"
                variant={tab === "task" ? "default" : "outline"}
                onClick={() => setTab("task")}
              >
                {translate("lago.customer_list.preview.add_task")}
              </Button>
            </div>
          </div>

          {tab === "note" && (
            <QuickNoteForm
              companyId={company.id}
              contacts={contacts}
              invalidateKey={invalidateKey}
            />
          )}
          {tab === "task" && (
            <QuickTaskForm
              primaryContact={primaryContact}
              invalidateKey={invalidateKey}
            />
          )}
        </CardContent>
      </Card>

      <Card>
        <CardHeader className="pb-3">
          <CardTitle className="flex items-center gap-2 text-sm font-bold">
            <Icon icon={MapPin} className="text-muted-foreground" />
            {translate("lago.customer_list.preview.core_info")}
            <VismaBadge size="xs" />
          </CardTitle>
        </CardHeader>
        <CardContent className="space-y-1 pt-0">
          {address ? (
            <p className="text-sm">{address}</p>
          ) : (
            <p className="text-muted-foreground text-sm">—</p>
          )}
          {company.phone_number && (
            <p className="text-sm">
              <a
                href={`tel:${company.phone_number}`}
                className="text-primary underline-offset-2 hover:underline"
              >
                {company.phone_number}
              </a>
            </p>
          )}
        </CardContent>
      </Card>

      <Card>
        <CardHeader className="pb-3">
          <CardTitle className="flex items-center gap-2 text-sm font-bold">
            <Icon icon={Users} className="text-muted-foreground" />
            {translate("lago.customer_list.preview.contacts")}
            {contacts.length > 0 && (
              <span className="text-muted-foreground font-normal">
                ({contacts.length})
              </span>
            )}
          </CardTitle>
        </CardHeader>
        <CardContent className="pt-0">
          {contacts.length === 0 ? (
            <p className="text-muted-foreground text-sm">
              {translate("lago.customer.empty.no_contacts")}
            </p>
          ) : (
            <ul className="space-y-2">
              {contacts.slice(0, 4).map((c) => (
                <li key={c.id} className="flex flex-wrap items-center gap-2">
                  <Link
                    to={`/contacts/${c.id}/show`}
                    className="text-primary text-sm hover:underline"
                  >
                    {fullName(c)}
                  </Link>
                  <ContactStatusBadge status={c.status} />
                  {c.title && (
                    <span className="text-muted-foreground text-sm">
                      · {c.title}
                    </span>
                  )}
                </li>
              ))}
            </ul>
          )}
        </CardContent>
      </Card>

      <Card>
        <CardHeader className="pb-3">
          <CardTitle className="flex items-center gap-2 text-sm font-bold">
            {translate("lago.customer_list.preview.sales_mini")}
            <VismaBadge size="xs" />
          </CardTitle>
        </CardHeader>
        <CardContent className="pt-0">
          <div className="text-muted-foreground rounded-md border border-dashed p-3 text-center text-sm">
            {translate("lago.customer.empty.sales_development_pending_visma")}
          </div>
        </CardContent>
      </Card>
    </div>
  );
}
